SELECT "Patient"."ID", "Patient"."SEX", "Patient"."Birthday"
FROM "Examination" INNER JOIN "Patient" ON "Examination"."ID" = "Patient"."ID"
WHERE "Examination"."LDH" > 500;

SELECT COUNT(*) AS "patient_count"
FROM "Patient"
WHERE "IGG" > 900 AND "IGG" < 2000 AND "symptoms" IS NOT NULL AND "symptoms" != '';
